// Generated from controller.js. Edit configuration via build-flow.js, then reimport.
const module = {exports:{}};
'use strict';
function step(state, event, now, config) {
  const s = state ? JSON.parse(JSON.stringify(state)) : {
    connected:false, armed:false, mode:'AUTO', requested:'OFF', lastSent:null,
    temperatura:null, humedad:null, nivel:null, lowWater:null
  };
  const c = config;
  const finite = x => typeof x === 'number' && Number.isFinite(x);
  const topicOK = x => typeof x === 'string' && x.length > 0 && !/[+#\u0000]/.test(x);
  const prefixOK = topicOK(c.prefix) && !c.prefix.includes('CHANGE_ME') && !c.prefix.endsWith('/');
  const mappingOK = prefixOK && topicOK(c.relayTopic) &&
    !c.relayTopic.startsWith(c.prefix + '/') &&
    typeof c.onPayload === 'string' && c.onPayload.length > 0 &&
    typeof c.offPayload === 'string' && c.offPayload.length > 0 && c.onPayload !== c.offPayload;
  const controlOK = finite(c.onBelow) && finite(c.offAt) && c.onBelow < c.offAt &&
    finite(c.staleMs) && c.staleMs > 0;
  let forceOff = false;
  const reset = () => {
    s.armed=false; s.mode='AUTO'; s.requested='OFF'; s.lastSent=null;
    s.temperatura=null; s.humedad=null; s.nivel=null; s.lowWater=null;
  };
  if (event.kind === 'connection' && event.connected !== s.connected) {
    reset(); s.connected = event.connected === true; forceOff = s.connected;
  }
  if (event.kind === 'arm') {
    reset(); s.armed=s.connected && mappingOK && controlOK; forceOff=true;
  }
  if (event.kind === 'stop') { reset(); forceOff=true; }
  if (!mappingOK || !controlOK) { s.armed=false; s.mode='AUTO'; s.requested='OFF'; }

  if (event.kind === 'connection' || event.kind === 'feedback') {
    if (!s.connected) s.relayReported = null;
    else if (event.kind === 'feedback' && !event.retain && ['0','1'].includes(event.payload)) {
      s.relayReported = event.payload === '1' ? 'ON' : 'OFF';
    }
  }
  const specs = {temperatura:['C',-40,100],humedad:['percent',0,100],nivel:['percent',0,100]};
  if (specs[event.kind] && event.retain !== true) {
    let p = event.payload;
    if (typeof p === 'string') { try { p=JSON.parse(p); } catch (_) { p=null; } }
    if (event.kind === 'nivel' && finite(p)) p = {value:p,unit:'percent',valid:true};
    // Bare numbers share the lab topics with structured Sense HAT measurements.
    const unrelatedNumber = typeof p === 'number' && ['temperatura','humedad'].includes(event.kind);
    if (!unrelatedNumber) {
      const [unit,min,max] = specs[event.kind];
      s[event.kind] = p && p.valid === true && p.unit === unit && finite(p.value) &&
        p.value >= min && p.value <= max ? {value:p.value,at:now} : null;
    }
  }
  const fresh = key => s[key] != null && now >= s[key].at && now-s[key].at < c.staleMs;
  const temperatureOK = fresh('temperatura');
  const humidityOK = fresh('humedad');
  const waterOK = fresh('nivel');
  let level = {value:null,unit:'percent',valid:false};
  if (waterOK) {
    const percent = s.nivel.value;
    level={value:percent,unit:'percent',valid:true};
    if (percent < c.lowBelow) s.lowWater=true;
    else if (percent >= c.lowClearAt || s.lowWater === null) s.lowWater=false;
  } else s.lowWater=null;

  if (event.kind === 'manual' && event.retain !== true && s.armed && temperatureOK &&
      ['ON','OFF','AUTO'].includes(event.payload)) s.mode=event.payload;
  if (!s.armed || !s.connected || !temperatureOK || !controlOK) {
    s.requested='OFF'; s.mode='AUTO';
  } else if (s.mode !== 'AUTO') s.requested=s.mode;
  else if (s.temperatura.value < c.onBelow) s.requested='ON';
  else if (s.temperatura.value >= c.offAt) s.requested='OFF';

  let relay=null;
  if (mappingOK && s.connected && (forceOff || (s.armed && s.requested !== s.lastSent))) {
    const requested=forceOff ? 'OFF' : s.requested;
    relay={topic:c.relayTopic,payload:requested === 'ON' ? c.onPayload : c.offPayload,qos:0,retain:false};
    s.lastSent=requested;
  }
  const faults=[];
  if (!s.connected) faults.push('mqtt-disconnected');
  if (!mappingOK) faults.push('relay-configuration');
  if (!controlOK) faults.push('control-configuration');
  if (!temperatureOK) faults.push('temperature-invalid-or-stale');
  if (!humidityOK) faults.push('humidity-invalid-or-stale');
  if (!waterOK) faults.push('water-invalid-or-stale');
  return {state:s, relay, level, status:{mode:s.mode,armed:s.armed,connected:s.connected,
    requested:s.requested,actual:'UNKNOWN',temperature:temperatureOK?s.temperatura.value:null,
    relayReported:s.relayReported || null,
    humidity:humidityOK?s.humedad.value:null,level:level.value,lowWater:s.lowWater,faults}};
}
module.exports = {step};

const config={"broker":"broker.hivemq.com","port":1883,"prefix":"IIoT/grupo99","relayTopic":"IIoT/9/relay/0/set","onPayload":"1","offPayload":"0","onBelow":30,"offAt":31,"lowBelow":20,"lowClearAt":25,"staleMs":15000,"feedbackTopic":"IIoT/9/relay/0"};
const demo=false;
let state=context.get('greenhouse');
let event;
if (demo && msg.kind === 'reset-demo') {
  state=module.exports.step(undefined,{kind:'connection',connected:true},Date.now(),config).state;
  event={kind:'arm'};
} else if (msg.status) {
  event={kind:'connection',connected:msg.status.fill === 'green'};
} else if (config.feedbackTopic && msg.topic === config.feedbackTopic) {
  event={kind:'feedback',payload:msg.payload,retain:msg.retain};
} else if (msg.kind) {
  event=msg;
} else {
  const prefix=config.prefix+'/';
  if (typeof msg.topic !== 'string' || !msg.topic.startsWith(prefix)) return null;
  const kind=msg.topic.slice(prefix.length);
  if (!['temperatura','humedad','nivel','manual'].includes(kind)) return null;
  event={kind,payload:msg.payload,retain:msg.retain};
}
const result=module.exports.step(state,event,Date.now(),config);
context.set('greenhouse',result.state);
const status={...result.status,simulation:demo};
node.status({fill:status.armed?'green':'yellow',shape:status.armed?'dot':'ring',text:status.mode+' / requested '+status.requested+' / relé '+(status.relayReported || '?')+(status.lowWater?' / AGUA BAJA':'')});
const telemetry=(!demo && status.connected) ? [
  {topic:config.prefix+'/estado',payload:JSON.stringify(status),qos:0,retain:false}
] : null;
return [result.relay,telemetry,{payload:status}];

function toDisplayMessage(msg, allowPlainNumbers = true) {
  if (msg.retain === true) return null;
  let data = msg.payload;
  if (typeof data === 'string') {
    if (data.length > 1024) return null;
    try { data = JSON.parse(data); } catch (_) { return null; }
  }
  const humidity = msg.topic === "IIoT/grupo99/humedad";
  const unit = humidity ? "percent" : "C";
  const value = allowPlainNumbers && typeof data === 'number' ? data :
    data && data.valid === true && data.unit === unit ? data.value : null;
  if (typeof value !== 'number' || !Number.isFinite(value) ||
      value < (humidity ? 0 : -40) || value > 100) return null;
  // Only this numeric argument reaches exec; discard unrelated message fields.
  return {payload: value.toFixed(1)};
}
const readings = context.get('readings') || {};
const now = Date.now();
if (msg.topic) {
  const result = toDisplayMessage(msg, false);
  if (result) {
    const key = msg.topic === 'IIoT/grupo99/humedad' ? 'humidity' : 'temperature';
    readings[key] = {value: result.payload, at: now};
    context.set('readings', readings);
    context.set('pending', true);
  }
  return null;
}
if (!context.get('pending')) return null;
context.set('pending', false);
const fresh = key => readings[key] && now - readings[key].at < 15000 ? readings[key].value : '';
const temperature = fresh('temperature');
const humidity = fresh('humidity');
if (!temperature && !humidity) return null;
return {payload: [temperature, humidity && '--humidity ' + humidity].filter(Boolean).join(' ')};
